{
  "name": "onAfterSend",
  "type": "function",
  "description": "Fired when sending a message succeeded or failed.",
  "permissions": ["compose"],
  "parameters": [
    {
      "name": "tab",
      "$ref": "tabs.Tab",
      "description": "The tab of the associated compose window. By the time the event listener is called, this window may have already been destroyed."
    },
    {
      "name": "sendInfo",
      "type": "object",
      "properties": {
        "mode": {
          "type": "string",
          "description": "The used send mode.",
          "enum": ["sendNow", "sendLater"]
        },
        "error": {
          "type": "string",
          "description": "An error description, if sending the message failed.",
          "optional": true
        },
        "headerMessageId": {
          "type": "string",
          "description": "The header messageId of the outgoing message. Only included for actually sent messages.",
          "optional": true
        },
        "messages": {
          "type": "array",
          "items": {
            "$ref": "messages.MessageHeader"
          },
          "description": "Copies of the sent message. The number of created copies depends on the applied file carbon copy configuration (fcc). The <permission>messagesRead</permission> permission is required for this property to be included."
        },
        "details": {
          "$ref": "ComposeDetails",
          "description": "The $(ref:compose.ComposeDetails) of the send message."
        }
      }
    }
  ]
},
{
  "name": "onAfterSave",
  "type": "function",
  "description": "Fired when saving a message as draft or template succeeded or failed.",
  "permissions": ["compose"],
  "parameters": [
    {
      "name": "tab",
      "$ref": "tabs.Tab"
    },
    {
      "name": "saveInfo",
      "type": "object",
      "properties": {
        "mode": {
          "type": "string",
          "description": "The used save mode.",
          "enum": ["autoSave", "draft", "template"]
        },
        "error": {
          "type": "string",
          "description": "An error description, if saving the message failed.",
          "optional": true
        },
        "messages": {
          "type": "array",
          "items": {
            "$ref": "messages.MessageHeader"
          },
          "description": "An array with exactly one element, the saved message. The <permission>messagesRead</permission> permission is required for this property to be included."
        },
        "details": {
          "$ref": "ComposeDetails",
          "description": "The $(ref:compose.ComposeDetails) of the saved message."
        }
      }
    }
  ]
},
